  function media(key, overrides) {
    const base = MEDIA_LIBRARY[key];
    const next = overrides || {};
    return {
      fit: base.fit || "cover",
      focalX: base.focalX ?? 50,
      focalY: base.focalY ?? 50,
      preserveTextSafeArea: Boolean(base.preserveTextSafeArea),
      role: base.role || "editorial",
      loadingTier: base.loadingTier || "deferred",
      ...base,
      ...next,
      alt: {
        ...base.alt,
        ...(next.alt || {}),
      },
    };
  }

  function publicMedia(src, titleVi, titleEn, overrides) {
    const next = overrides || {};
    return {
      src,
      width: next.width || 1200,
      height: next.height || 900,
      ratio: next.ratio || "4 / 3",
      fit: next.fit || "cover",
      focalX: next.focalX ?? 50,
      focalY: next.focalY ?? 50,
      preserveTextSafeArea: Boolean(next.preserveTextSafeArea),
      role: next.role || "archive",
      loadingTier: next.loadingTier || "near",
      alt: {
        vi: titleVi,
        en: titleEn || titleVi,
      },
    };
  }

