        taglineEn: "Module điện tử",
        summaryVi: "Cảm biến khí gas MQ5 được sử dụng để phát hiện khí gas trong môi trường. Cảm biến này có độ nhạy cao, khả năng phản hồi nhanh và cho phép điều chỉnh độ nhạy thông qua biến trở.\n\nCảm biến MQ5 có khả nă...",
        summaryEn: "Cảm biến khí gas MQ5 được sử dụng để phát hiện khí gas trong môi trường. Cảm biến này có độ nhạy cao, khả năng phản hồi nhanh và cho phép điều chỉnh độ nhạy thông qua biến trở.\n\nCảm biến MQ5 có khả nă...",
        descriptionVi: "Thông số kỹ thuật : Điện áp hoạt động: 5V DC. Chip chính: Cảm biến khí MQ-5, tích hợp với IC so sánh LM393. Kích thước: Khoảng 32mm x 20mm x 27mm Đầu ra: DOUT (Digital Output): Tín hiệu số (0 hoặc 1), tín hiệu thấp khi phát hiện khí gas. AOUT (Analog Output): Tín hiệu analog (0-5V) tương ứng với nồng độ khí gas. Dòng tiêu thụ: Khoảng 150-200mA khi hoạt động. Loại khí phát hiện: LPG (khí hóa lỏng), khí tự nhiên, khí than, khí metan (CH4). Độ nhạy: Cao với LPG, khí tự nhiên; thấp với hơi",
