        summaryVi: "Module Điều Khiển Động Cơ L293D - Arduino Motor Control Shield sử dụng 2 IC cầu H L293D hoàn chỉnh với các chế độ bảo vệ và 1 IC logic 74HC595 để điều khiển các động cơ.",
